def choose_move(observation):
    sx, sy = observation.get("self_position", (0, 0))
    env = observation.get("environment_name", "resource_collection")
    ox, oy = observation.get("opponent_position", (sx, sy))
    grid_width = observation.get("grid_width", 10)
    grid_height = observation.get("grid_height", 10)

    def direction_towards(target_x, target_y):
        dx = 0 if target_x == sx else (1 if target_x > sx else -1)
        dy = 0 if target_y == sy else (1 if target_y > sy else -1)
        return [dx, dy]

    # Defensive access
    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return direction_towards(ox, oy)
        corners = [
            [0, 0],
            [0, grid_height - 1],
            [grid_width - 1, 0],
            [grid_width - 1, grid_height - 1]
        ]
        # Pick the corner farthest from opponent for robustness
        target = max(corners, key=lambda c: abs(c[0] - ox) + abs(c[1] - oy))
        return direction_towards(target[0], target[1])

    elif env == "territory_control":
        targets = (
            observation.get("unclaimed_cells")
            or observation.get("opponent_territory")
            or []
        )
        if not targets:
            return [0, 0]
        # Move towards the closest target for robustness
        best_target = min(targets, key=lambda t: abs(t[0] - sx) + abs(t[1] - sy))
        return direction_towards(best_target[0], best_target[1])

    # Resource collection
    resources = observation.get("resources") or []
    if resources:
        best_resource = min(resources, key=lambda r: abs(r[0] - sx) + abs(r[1] - sy))
        return direction_towards(best_resource[0], best_resource[1])
    # No resources, move randomly or towards opponent for minimal heuristic
    return direction_towards(ox, oy)

